    13	  TrustedConfigSource,
    14	} from "./core/types.js";
    15	import { GENERATED_MODEL_REGISTRY } from "./config.generated.js";
    16	
    17	const execFileAsync = promisify(execFile);
    18	
    19	/**
    20	 * Zod schema for multi-model configuration (SDD Section 2.7).
    21	 * Validated at startup; all fields have sensible defaults so partial config works.
    22	 */
