     1	/**
     2	 * cycle-129 D-7.7 (DEC-0150): the multi-model run's voice outcome — the completion banner's completed/planned count, the
     3	 * DEGRADED decision, the WARN line naming the voices, and the exit code under `bridgebuilder.exit_on_degraded`.
     4	 *
     5	 * Pure functions so the exit paths are testable without running main.ts (which executes on import).
     6	 */
     7	import { computeVerdictBand, type MultiModelReviewResult } from "./multi-model-pipeline.js";
     8	
     9	export interface VoiceOutcome {
    10	  /** Voices this review was expected to run. */
    11	  planned: number;
    12	  /** Voices whose result completed (a response and no error). */
    13	  completed: number;
    14	  /** The aggregate verdict-quality band (null when no voice carried an envelope). */
    15	  band: "APPROVED" | "DEGRADED" | "FAILED" | null;
    16	  /** Planned voices without a completed result, as `provider/model`. */
    17	  incomplete: string[];
    18	  /** completed < planned, or the band is DEGRADED or FAILED. */
    19	  degraded: boolean;
    20	}
    21	
    22	type OutcomeInput = Pick<MultiModelReviewResult, "modelResults" | "voicesPlanned">;
    23	
    24	/** The outcome of one item's multi-model review. */
    25	export function summarizeVoices(result: OutcomeInput): VoiceOutcome {
    26	  const completedLabels = result.modelResults
    27	    .filter((r) => r.response !== undefined && r.error === undefined)
    28	    .map((r) => `${r.provider}/${r.model}`);
    29	  // (an older pipeline result without voicesPlanned: every attempted voice was planned)
    30	  const plannedLabels = result.voicesPlanned ?? result.modelResults.map((r) => `${r.provider}/${r.model}`);
    31	  const remaining = [...completedLabels];
    32	  const incomplete: string[] = [];
    33	  for (const label of plannedLabels) {
    34	    const i = remaining.indexOf(label);
    35	    if (i >= 0) remaining.splice(i, 1);
    36	    else incomplete.push(label);
    37	  }
    38	  const band = computeVerdictBand(result.modelResults.map((r) => ({ verdictQuality: r.response?.verdictQuality })));
    39	  const completed = completedLabels.length;
    40	  const planned = plannedLabels.length;
    41	  return {
    42	    planned,
    43	    completed,
    44	    band,
    45	    incomplete,
    46	    degraded: completed < planned || band === "DEGRADED" || band === "FAILED",
    47	  };
    48	}
    49	
    50	/** The run-level totals across every reviewed item (the banner prints these). */
    51	export function totalVoices(outcomes: VoiceOutcome[]): { completed: number; planned: number; degraded: boolean; incomplete: string[] } {
    52	  const incomplete: string[] = [];
    53	  for (const o of outcomes) for (const v of o.incomplete) if (!incomplete.includes(v)) incomplete.push(v);
    54	  return {
    55	    completed: outcomes.reduce((n, o) => n + o.completed, 0),
    56	    planned: outcomes.reduce((n, o) => n + o.planned, 0),
    57	    degraded: outcomes.some((o) => o.degraded),
    58	    incomplete,
    59	  };
    60	}
    61	
    62	/** The process exit code for a completed multi-model run: `exitOnDegraded` when DEGRADED, else 0. */
    63	export function decideExitCode(degraded: boolean, exitOnDegraded: number): number {
    64	  return degraded ? exitOnDegraded : 0;
    65	}
    66	
    67	/** The one WARN line a DEGRADED run prints to stderr (callers grep `DEGRADED`; the voices are named). */
    68	export function degradedWarnLine(
    69	  totals: { completed: number; planned: number; incomplete: string[] },
    70	  bands: Array<VoiceOutcome["band"]>,
    71	  exitCode: number,
    72	): string {
    73	  const worst = bands.includes("FAILED") ? "FAILED" : bands.includes("DEGRADED") ? "DEGRADED" : null;
    74	  const voices = totals.incomplete.length > 0 ? `; incomplete voices: ${totals.incomplete.join(", ")}` : "";
    75	  const bandNote = worst !== null ? `; verdict quality: ${worst}` : "";
    76	  return `[bridgebuilder] WARN: DEGRADED — ${totals.completed}/${totals.planned} voices completed${voices}${bandNote} ` +
    77	    `(exit ${exitCode}; bridgebuilder.exit_on_degraded)`;
