   465	 */
   466	export function parseProviderDecls(raw: unknown, label: string, warnings: string[]): Record<string, ProviderDecl> {
   467	  const out: Record<string, ProviderDecl> = {};
   468	  if (raw === null || raw === undefined) return out;
